import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        int[] left = new int[26];
        boolean[] inside = new boolean[26];
        for (int i = 0; i < s.length(); i++) left[s.charAt(i) - 'a']++;
        StringBuilder st = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            left[c - 'a']--;
            if (inside[c - 'a']) continue;
            // A smaller letter on top can be dropped when another copy still follows.
            while (st.length() > 0) {
                char top = st.charAt(st.length() - 1);
                if (top >= c || left[top - 'a'] == 0) break;
                inside[top - 'a'] = false;
                st.setLength(st.length() - 1);
            }
            st.append(c);
            inside[c - 'a'] = true;
        }
        System.out.println(st);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"strings"
)

func main() {
	raw, _ := io.ReadAll(os.Stdin)
	s := strings.TrimSpace(string(raw))
	var left [26]int
	var inside [26]bool
	for i := 0; i < len(s); i++ {
		left[s[i]-'a']++
	}
	st := []byte{}
	for i := 0; i < len(s); i++ {
		c := s[i]
		left[c-'a']--
		if inside[c-'a'] {
			continue
		}
		// A smaller letter on top can be dropped when another copy still follows.
		for len(st) > 0 && st[len(st)-1] < c && left[st[len(st)-1]-'a'] > 0 {
			inside[st[len(st)-1]-'a'] = false
			st = st[:len(st)-1]
		}
		st = append(st, c)
		inside[c-'a'] = true
	}
	fmt.Println(string(st))
}
